mapper.select:
SELECT p.postId as postId, p.title, p.likeCount as likeCount, p.dislikeCount as dislikeCount, p.viewCount as viewCount, u.nickName as nickName, p.createAt as createAt FROM post_tbl p JOIN user_tbl u ON p.userId = u.userId WHERE p.postCodeId = #{postCodeId}
AND (p.title LIKE CONCAT('%', #{searchKeyword}, '%') OR p.content LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY p.postId DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE post_tbl
SET viewCount = viewCount + 1
WHERE postId = #{postId}

UPDATE post_tbl
SET likeCount = likeCount + 1
WHERE postId = #{postId}

UPDATE post_tbl
SET likeCount = likeCount - 1
WHERE postId = #{postId}

UPDATE post_tbl
SET dislikeCount = dislikeCount + 1
WHERE postId = #{postId}

UPDATE post_tbl
SET dislikeCount = dislikeCount - 1
WHERE postId = #{postId}
